    \begin{tikzpicture}

    \node[align=left,draw,rectangle] at (0,0) (main) 
    {\Cref{thm:consensus time large alphanorm} \\$\Pr\qty[\taucons>\frac{C\log n}{\alphanorm_0}]\leq O(n^{-1})$.};



    \node[align=left,draw,rectangle] at (5.6,0) (plurality) 
    {\cref{thm:plurality} (Plurality)\\
    If $\alpha_0(1)\geq \alpha_0(j)+C\sqrt{\log n/n}$ for $\forall j\neq 1$, \\
    $\alpha_T(1)=1$ w.h.p.~for $T\leq O\qty(\frac{\log n}{\alphanorm_0})$.};



    \node[align=left,draw,rectangle] at (0,-3.4) (gapamp) 
    {\cref{lem:gap amplification} (Bias amplification)\\
    For $\xdelta\geq c_*\sqrt{\log n/n}$, \\
    $\Pr\qty[\min\{\taudeltaplus,\tauiweak,\taujweak\}>\frac{C\log n}{\alphanorm_0}]$\\
    $\leq O(n^{-10})$.};



    \node[align=left,draw,rectangle] at (5.6,-3.4) (biasweak) 
    {\Cref{lem:initial bias weak} (Initial bias to weak)\\
    If $\alpha_0(i)\geq \alpha_0(j)+C\sqrt{\log n/n}$, \\
    $\Pr\qty[\taujweak>\frac{C\log n}{\alphanorm_0}]\leq O(n^{-10})$.};



    \node[align=left,draw,rectangle] at (10.6,-3.4) (vanish) 
    {\Cref{lem:weakvanish} (Weak vanishes)\\
    For weak $i$, \\
    $\Pr\qty[\tauivanish>\frac{C\log n}{\alphanorm_0}]$\\
    $\leq O(n^{-10})$.};



    \node[align=left,draw,rectangle] at (0,-6.8) (additive drift) 
    {\Cref{lem:additive drift} (Additive drift)\\
    For $\xdelta\geq 0.001/\sqrt{n}$, \\
    $\Pr\qty[\min\{\taudeltaplus,\tauiweak,\taujweak\}>\frac{1}{\alphanorm_0}]$\\
    $\leq 1-c$.};



    \node[align=left,draw,rectangle] at (5.6,-6.8) (deltaupweak) 
    {\Cref{lem:deltaupweak} (Multiplicative drift)\\
    $\Pr\qty[\min\{\taudeltaup, \taujweak\}>\frac{1}{\alphanorm_0}]$\\$
    \leq \exp\qty(-\Omega(n\min\{\delta_0^2,\alphanorm_0^2\}))$.};









    \node[align=left,draw,rectangle] at (0,-10.2) (OST) 
    {\Cref{lem:taudeltaplus OST} (OST and $\delta_t^2$), \\
    \Cref{lem:taudeltaplus general,lem:taudeltaplus one step sync}};








    \node[align=left,draw,rectangle] at (5.6,-10.2) (drift) 
    {\Cref{lem:drift analysis for basic} \\ (Drift analysis for basic quantities)};



